'use client';

import { useState } from 'react';

const VEHICLE_ICONS = ['🚗', '🚙', '🚕', '🛻', '🚐', '🚌'];

function AlertCard({ alert, isNew }) {
  const [expanded, setExpanded] = useState(false);
  const icon = VEHICLE_ICONS[alert.id % VEHICLE_ICONS.length];

  const getBadgeClass = (status) => {
    if (status === 'No Plate') return 'badge-noplate';
    if (status === 'Suspicious') return 'badge-suspicious';
    return 'badge-clear';
  };

  return (
    <div className={`alert-card ${isNew ? 'new-alert' : ''}`}>
      {/* Vehicle image placeholder */}
      <div className="alert-card-img-placeholder">
        <span style={{ fontSize: '32px', position: 'relative', zIndex: 1 }}>{icon}</span>
        {/* Fake detection box on image */}
        <div style={{
          position: 'absolute',
          top: '15%', left: '30%',
          width: '40%', height: '65%',
          border: `1.5px solid ${alert.status === 'No Plate' ? '#ef4444' : '#f59e0b'}`,
          borderRadius: '2px',
          boxShadow: `0 0 6px ${alert.status === 'No Plate' ? 'rgba(239,68,68,0.3)' : 'rgba(245,158,11,0.3)'}`,
          zIndex: 2,
        }} />
        <div style={{
          position: 'absolute',
          top: '4px', right: '8px',
          fontFamily: 'var(--font-mono)',
          fontSize: '8px',
          color: 'rgba(255,255,255,0.4)',
          zIndex: 3,
        }}>
          FRAME #{(alert.id * 347 + 1120).toString().padStart(5, '0')}
        </div>
      </div>

      <div className="alert-card-body">
        <div className="alert-card-top">
          <span className="alert-time">⏱ {alert.time}</span>
          <span className={`alert-status-badge ${getBadgeClass(alert.status)}`}>
            {alert.status}
          </span>
        </div>

        <div className="alert-location">
          📍 {alert.location || 'SECTOR-A / CAM-001'}
        </div>

        {expanded && (
          <div style={{
            padding: '8px',
            background: 'rgba(0,0,0,0.3)',
            borderRadius: '5px',
            marginBottom: '8px',
            fontFamily: 'var(--font-mono)',
            fontSize: '9px',
            color: 'var(--text-muted)',
            lineHeight: '1.8',
          }}>
            <div>CONF: {alert.confidence || '91.4'}%</div>
            <div>VEHICLE: {alert.vehicleType || 'SEDAN'}</div>
            <div>COLOR: {alert.color || 'DARK GRAY'}</div>
            <div>DIRECTION: {alert.direction || 'NORTHBOUND'}</div>
            <div>SPEED: {alert.speed || '~45'} KM/H</div>
          </div>
        )}

        <button
          className="btn-view-detail"
          onClick={() => setExpanded(!expanded)}
        >
          {expanded ? '▲ HIDE DETAIL' : '▼ VIEW DETAIL'}
        </button>
      </div>
    </div>
  );
}

export default function AlertPanel({ alerts, newAlertId }) {
  return (
    <div className="panel" style={{ height: '100%' }}>
      <div className="panel-header">
        <span className="panel-title">Alert Feed</span>
        <span
          className="panel-badge"
          style={{
            background: alerts.length > 0 ? 'rgba(239,68,68,0.12)' : 'rgba(100,116,139,0.1)',
            color: alerts.length > 0 ? '#ef4444' : '#64748b',
            border: `1px solid ${alerts.length > 0 ? 'rgba(239,68,68,0.25)' : 'rgba(100,116,139,0.2)'}`,
          }}
        >
          {alerts.length} EVENTS
        </span>
      </div>

      <div className="panel-body">
        {alerts.length === 0 ? (
          <div style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            height: '200px',
            gap: '10px',
            color: 'var(--text-muted)',
          }}>
            <div style={{ fontSize: '32px', opacity: 0.3 }}>◎</div>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '10px', letterSpacing: '2px' }}>
              NO ALERTS
            </div>
          </div>
        ) : (
          <div className="alert-list">
            {[...alerts].reverse().map(alert => (
              <AlertCard
                key={alert.id}
                alert={alert}
                isNew={alert.id === newAlertId}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
